function calculateCharge(order: any) {
  switch (order.type) {
    case 'online':
      return order.items.length * 10 + 5;
    case 'instore':
      return order.items.length * 8;
    case 'pickup':
      return order.items.length * 5 - order.discount;
    default:
      throw new Error('Unknown order type');
  }
}

class Invoice {
  calculateTotal(customer: any, items: any[]) {
    if (customer.isEnterprise) {
      return items.reduce((s, i) => s + i.price, 0) * 0.95;
    } else {
      return items.reduce((s, i) => s + i.price, 0);
    }
  }
}

