// Version B
abstract class OrderBase { constructor(public items: any[], public discount: number) {} abstract charge(): number; }
class OnlineOrder extends OrderBase { charge() { return this.items.length * 10 + 5; } }
class InStoreOrder extends OrderBase { charge() { return this.items.length * 8; } }
class PickupOrder extends OrderBase { charge() { return this.items.length * 5 - this.discount; } }
function createOrder(type: string, items: any[], discount: number) {
  if (type === 'online') return new OnlineOrder(items, discount);
  if (type === 'instore') return new InStoreOrder(items, discount);
  return new PickupOrder(items, discount);
}
